import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { hash, projectDetail, validateReviewedBatch, loadRecovery, applyReviewedBatch } from '../scripts/apply-reviewed-nse-ipos.mjs';
const root=process.cwd(), dir=process.env.SOURCE_DIR;
const src=JSON.parse(fs.readFileSync(path.join(dir,'sources.json')));
assert.equal(src.run_id,'36170193878');
assert.equal(src.source_commit_sha,'5e6a434b7fdbb1245116c78dee8f44534937fa02');
const queuePath='data/discovery/ipo-universe-review-2026-09-25-batch5.json', queueBytes=fs.readFileSync(path.join(root,queuePath)), queue=JSON.parse(queueBytes);
assert.equal(hash(queueBytes),src.input.sha256);
assert.equal(src.rows.length,17);
for(const s of src.rows){const bytes=fs.readFileSync(path.join(dir,s.file));assert.equal(s.status,200);assert.equal(bytes.length,s.bytes);assert.equal(hash(bytes),s.sha256);}
const ps=src.rows.find(s=>s.kind==='past'), past=JSON.parse(fs.readFileSync(path.join(dir,ps.file)));
const ds=src.rows.find(s=>s.kind==='deployed_baseline'), db=fs.readFileSync(path.join(dir,ds.file)), data=JSON.parse(db);
assert.equal(hash(db),'30bf80d968e3f13fe92a46b7d19a0f8f5260f93ecb31c5707eb4ca640fcbeff1');
assert.equal(data.records.length,1269);assert.deepEqual(db,fs.readFileSync(path.join(root,'data/ipos.json')));
const approved=['TEJA','VMOBILE','KNACK','ICELCO','KUSUMGAR','HAPPY','LASERPOWER','SBIFUNDS','CMLL','METALIC','INDOMIM','LCL','PROPSHOP','MANIPALHOS','JNPR'];
assert.deepEqual(queue.candidates.map(c=>c.nse_symbol),approved);
const ev=(s,p)=>({url:s.url,final_url:s.final_url,http_status:s.status,publication_date:null,collected_at:s.collected_at,response_sha256:s.sha256,projection_sha256:hash(JSON.stringify(p)),artifact_file:s.file});
const provenance={source_run_id:src.run_id,source_snapshot_commit:src.source_commit_sha,source_artifact_id:10880128428,source_artifact_sha256:'760db5e15a4ec505738f0b1a36f97026d9f210648c3e63720bb12fb575bdea49',queue_path:queuePath};
const manifest={schema_version:'1.0.0',verifier_version:'1.0.0',...provenance,queue_sha256:hash(JSON.stringify(queue)),projection_method:'literal_selected_json_fields_all_used_titles_retained',scope_note:'All 15 pinned batch5 candidates independently reviewed as initial equity IPOs. TEJA is fixed price: preserve missing price_band. Keep market lot and minimum bid distinct. No inferred issue size or application amount.',entries:queue.candidates.map(c=>{
 const s=src.rows.find(s=>s.kind==='ipo_detail'&&s.symbol===c.nse_symbol),detail=projectDetail(JSON.parse(fs.readFileSync(path.join(dir,s.file)))),row=past[c.row_index];
 assert.equal(row.symbol,c.nse_symbol);assert.equal(past.filter(r=>r.symbol===c.nse_symbol).length,1);
 return {candidate:c,decision:'verified_initial_equity_ipo',detail_source:ev(s,detail),detail,past_source:ev(ps,row),past_row:row};
})};
const checked=validateReviewedBatch(manifest,queue);assert.equal(checked.length,15);
const facts=Object.fromEntries(['listing_date','open_date','close_date','issue_price','price_band','market_lot','minimum_bid_quantity'].map(f=>[f,checked.filter(c=>c.facts[f]).length]));
assert.deepEqual(facts,{listing_date:15,open_date:15,close_date:15,issue_price:15,price_band:14,market_lot:6,minimum_bid_quantity:9});
const raw=loadRecovery(root),before=JSON.stringify(raw),plan=applyReviewedBatch(raw,data,manifest,queue,'data/verified-nse-ipos/2026-09-25-batch5.json');
assert.deepEqual(plan.stats,{added:15,already_present:0});assert.equal(JSON.stringify(raw),before);
const second=applyReviewedBatch(plan.recovery,data,manifest,queue,'data/verified-nse-ipos/2026-09-25-batch5.json');assert.deepEqual(second.stats,{added:0,already_present:15});assert.deepEqual(second.recovery,plan.recovery);
const review={schema_version:'1.0.0',status:'reviewed_15_approved_no_holds',reviewed_at:'2026-09-25T17:58:00Z',...provenance,baseline:{public_records:data.records.length,public_sha256:hash(db),dataset_generated_at:data.generated_at,snapshot_fetched_at:ds.collected_at,source_snapshot_matches_served_bytes:true},stats:{reviewed_candidates:15,verified_initial_equity_ipos:15,held:0,excluded:0,approved_exact_missing:15,approved_identity_conflicts:0,verified_facts:89,...facts},sources:{successful_detail_responses:15,original_response_hashes_checked:17,past_response_sha256:ps.sha256},parser_changes:[],scope_notes:['No parser change needed; existing fail-closed source and identity checks passed for all 15.','TEJA fixed price INR 220 is independently corroborated, not converted into a price band.','Six market lots and nine minimum bid quantities stay separate; missing optional monetary fields remain null.','This source snapshot contains an intervening historical-PDF update; use this freshly fetched baseline for batch5 deltas.'],entries:checked.map(c=>({symbol:c.candidate.nse_symbol,issuer_name:c.issuer_name,observed_alias:c.candidate.issuer_name,isin:c.isin,board:c.candidate.board,decision:'approved_verified_initial_equity_ipo',listing_date:c.facts.listing_date.value,offer_period:{open:c.facts.open_date.value,close:c.facts.close_date.value},offering_evidence:c.offer,recovery_matches:[],published_matches:[],fact_count:Object.keys(c.facts).length})),held:[]};
const mb=JSON.stringify(manifest)+'\n', rb=JSON.stringify(review,null,2)+'\n';
assert.equal(hash(mb),'7dc2e97b254af58b59edad137ee2150c5740d6f78cdcd40fcdf36343dafefd1a');
assert.equal(hash(rb),'35df87dfad8268f193d828cb8b0b598605207a68c5bd8f0fad86d3a93d86ac5f');
fs.writeFileSync(path.join(root,'data/verified-nse-ipos/2026-09-25-batch5.json'),mb);
fs.writeFileSync(path.join(root,'data/discovery/nse-universe-batch5-review-2026-09-25.json'),rb);
console.log(JSON.stringify({stats:review.stats,manifest_sha256:hash(mb),review_sha256:hash(rb),baseline:review.baseline,plan:plan.stats}));
